// paprikaValue helpers intentionally accept the loose scalar types emitted by
// different Paprika versions instead of assuming every export uses strings.
func paprikaString(values map[string]any, key string) string {
	value, ok := values[key]
	if !ok || value == nil {
		return ""
	}
	switch typed := value.(type) {
	case string:
		return strings.TrimSpace(typed)
	case json.Number:
		return typed.String()
	case float64:
		if typed == math.Trunc(typed) {
			return strconv.FormatInt(int64(typed), 10)
		}
		return strconv.FormatFloat(typed, 'f', -1, 64)
	default:
		return strings.TrimSpace(fmt.Sprint(typed))
	}
}

func paprikaInt(values map[string]any, key string) int {
	value := paprikaString(values, key)
	if value == "" {
		return 0
	}
	if parsed, err := strconv.Atoi(value); err == nil {
		return parsed
	}
	if parsed, err := strconv.ParseFloat(value, 64); err == nil {
		return int(parsed)
	}
	return 0
}

// paprikaHTMLBreakTags are safe break/block markup patterns Paprika exports
// commonly carry; each becomes a plain newline so the downstream line and
// step splitters can work on ordinary text.
var paprikaHTMLBreakTags = []string{
	"<br>", "<br/>", "<br />",
	"</li>", "</p>", "</div>", "</h1>", "</h2>", "</h3>", "</h4>", "</h5>", "</h6>", "</tr>",
}

var (
	paprikaHTMLTagPattern   = regexp.MustCompile(`(?i)</?[a-zA-Z][a-zA-Z0-9]*(?:\s[^<>]*)?>`)
	paprikaBlankLinePattern = regexp.MustCompile(`\n{3,}`)
)

// paprikaDecodeHTMLEntities resolves named and numeric HTML character
// references in a single pass; text without "&" is returned unchanged.
func paprikaDecodeHTMLEntities(text string) string {
	if !strings.Contains(text, "&") {
		return text
	}
	var sb strings.Builder
	for start := 0; start < len(text); {
		at := strings.IndexByte(text[start:], '&')
		if at < 0 {
			sb.WriteString(text[start:])
			break
		}
		pos := start + at
		sb.WriteString(text[start:pos])
		end := pos + 1
		for end < len(text) && end < pos+11 && text[end] != ';' {
			end++
		}
		if end < len(text) && text[end] == ';' {
			candidate := text[pos : end+1]
			if decoded := html.UnescapeString(candidate); decoded != candidate {
				sb.WriteString(decoded)
				start = end + 1
				continue
			}
		}
		sb.WriteByte('&')
		start = pos + 1
	}
	return sb.String()
}

// paprikaNormalizeText reduces deterministic HTML presentation artifacts in
// Paprika text fields to plain text: common entities are decoded, break and
// block markup becomes newlines, remaining simple tags are stripped,
// non-breaking spaces become ordinary spaces, and runs of blank lines collapse
// to a single blank line. Ordinary plain text is preserved apart from
// existing trimming behavior.
func paprikaNormalizeText(raw string) string {
	text := paprikaDecodeHTMLEntities(raw)
	for _, tag := range paprikaHTMLBreakTags {
		text = strings.ReplaceAll(text, tag, "\n")
	}
	text = stripPaprikaHTMLTags(text)
	text = strings.ReplaceAll(text, "\u00a0", " ")
	text = strings.ReplaceAll(text, "\r\n", "\n")
	text = strings.ReplaceAll(text, "\r", "\n")
	lines := strings.Split(text, "\n")
	for index, line := range lines {
		lines[index] = strings.TrimSpace(line)
	}
	text = strings.Join(lines, "\n")
	text = paprikaBlankLinePattern.ReplaceAllString(text, "\n\n")
	return strings.TrimSpace(text)
}

// stripPaprikaHTMLTags removes the remaining simple HTML tags (opening and
// closing) from Paprika text; ordinary angle brackets that do not begin a
// tag (for example "3 < 4") are left untouched.
func stripPaprikaHTMLTags(text string) string {
	if !strings.Contains(text, "<") {
		return text
	}
	return paprikaHTMLTagPattern.ReplaceAllString(text, "")
}

func splitPaprikaLines(raw string) []string {
	raw = strings.ReplaceAll(raw, "\r\n", "\n")
	raw = strings.ReplaceAll(raw, "\r", "\n")
	lines := strings.Split(raw, "\n")
	result := make([]string, 0, len(lines))
	for _, line := range lines {
		line = strings.TrimSpace(line)
		line = strings.TrimLeftFunc(line, unicode.IsSpace)
		if line != "" {
			result = append(result, line)
		}
	}
	return result
}

func splitPaprikaSteps(raw string) []string {
	raw = strings.ReplaceAll(raw, "\r\n", "\n")
	raw = strings.ReplaceAll(raw, "\r", "\n")
	paragraphs := strings.Split(raw, "\n\n")
	result := make([]string, 0, len(paragraphs))
	for _, paragraph := range paragraphs {
		paragraph = strings.TrimSpace(paragraph)
		if paragraph == "" {
			continue
		}
		result = append(result, paragraph)
	}
	if len(result) == 1 && strings.Contains(result[0], "\n") {
		return splitPaprikaLines(result[0])
	}
	return result
}

func paprikaDurationSeconds(raw string) int32 {
	raw = strings.TrimSpace(strings.ToLower(raw))
	if raw == "" {
		return 0
	}
	if minutes, err := strconv.Atoi(raw); err == nil {
		return int32(minutes * 60)
	}
	var total float64
	fields := strings.FieldsFunc(raw, func(r rune) bool {
		return r == ',' || r == ';' || r == '+'
	})
	for _, part := range fields {
		tokens := strings.Fields(part)
		for index := 0; index < len(tokens); index++ {
			value, err := strconv.ParseFloat(tokens[index], 64)
			if err != nil {
				continue
			}
			unit := "min"
			if index+1 < len(tokens) {
				unit = tokens[index+1]
				index++
			}
			if strings.HasPrefix(unit, "h") {
				total += value * 60
			} else {
				total += value
			}
		}
	}
	return int32(total * 60)
}

func paprikaRecipeFromMap(values map[string]any) (*pb.PBRecipe, error) {
	name := paprikaString(values, "name")
	if name == "" {
		return nil, fmt.Errorf("Paprika recipe is missing name")
	}
	now := float64(time.Now().Unix())
	note := paprikaNormalizeText(paprikaString(values, "description"))
	if extra := paprikaNormalizeText(paprikaString(values, "notes")); extra != "" {
		if note != "" {
			note += "\n\n"
		}
		note += extra
	}
	recipe := &pb.PBRecipe{
		Identifier:        newRecipeID(),
		Timestamp:         now,
		CreationTimestamp: now,
		Name:              name,
		Note:              note,
		SourceName:        paprikaNormalizeText(paprikaString(values, "source")),
		SourceUrl:         paprikaString(values, "source_url"),
		NutritionalInfo:   paprikaNormalizeText(paprikaString(values, "nutritional_info")),
		Servings:          paprikaString(values, "servings"),
		PrepTime:          paprikaDurationSeconds(paprikaString(values, "prep_time")),
		CookTime:          paprikaDurationSeconds(paprikaString(values, "cook_time")),
		Rating:            int32(paprikaInt(values, "rating")),
		PaprikaIdentifier: paprikaString(values, "uid"),
		PreparationSteps:  splitPaprikaSteps(paprikaNormalizeText(paprikaString(values, "directions"))),
	}
	for _, line := range splitPaprikaLines(paprikaNormalizeText(paprikaString(values, "ingredients"))) {
		recipe.Ingredients = append(recipe.Ingredients, &pb.PBIngredient{
			RawIngredient: line,
			Name:          line,
		})
	}
	return recipe, nil
}

func decodePaprikaJSON(data []byte, sourcePath string) ([]paprikaImportRecipe, error) {
	decoder := json.NewDecoder(strings.NewReader(string(data)))
	decoder.UseNumber()
	var raw any
	if err := decoder.Decode(&raw); err != nil {
		return nil, fmt.Errorf("decoding %s: %w", sourcePath, err)
	}
	objects := []map[string]any{}
	switch typed := raw.(type) {
	case map[string]any:
		objects = append(objects, typed)
	case []any:
		for index, item := range typed {
			object, ok := item.(map[string]any)
			if !ok {
				return nil, fmt.Errorf("%s recipe %d is not an object", sourcePath, index+1)
			}
			objects = append(objects, object)
		}
	default:
		return nil, fmt.Errorf("%s does not contain a Paprika recipe object", sourcePath)
	}
	result := make([]paprikaImportRecipe, 0, len(objects))
	for index, object := range objects {
		recipe, err := paprikaRecipeFromMap(object)
		if err != nil {
			return nil, fmt.Errorf("%s recipe %d: %w", sourcePath, index+1, err)
		}
		result = append(result, paprikaImportRecipe{SourcePath: sourcePath, Recipe: recipe})
	}
	return result, nil
}

func readPaprikaRecipe(path string, reader io.Reader) ([]paprikaImportRecipe, error) {
	data, err := io.ReadAll(reader)
	if err != nil {
		return nil, fmt.Errorf("reading %s: %w", path, err)
	}
	if len(data) >= 2 && data[0] == 0x1f && data[1] == 0x8b {
		gz, err := gzip.NewReader(strings.NewReader(string(data)))
		if err != nil {
			return nil, fmt.Errorf("opening compressed Paprika recipe %s: %w", path, err)
		}
		decompressed, readErr := io.ReadAll(gz)
		closeErr := gz.Close()
		if readErr != nil {
			return nil, fmt.Errorf("decompressing %s: %w", path, readErr)
		}
		if closeErr != nil {
			return nil, fmt.Errorf("closing compressed Paprika recipe %s: %w", path, closeErr)
		}
		data = decompressed
	}
	return decodePaprikaJSON(data, path)
}

func loadPaprikaInput(path string) ([]paprikaImportRecipe, error) {
	info, err := os.Stat(path)
	if err != nil {
		return nil, fmt.Errorf("opening Paprika input: %w", err)
	}
	var paths []string
	if info.IsDir() {
		err := filepath.Walk(path, func(candidate string, candidateInfo os.FileInfo, walkErr error) error {
			if walkErr != nil {
				return walkErr
			}
			if candidateInfo.Mode().IsRegular() && strings.EqualFold(filepath.Ext(candidate), ".paprikarecipe") {
				paths = append(paths, candidate)
			}
			return nil
		})
		if err != nil {
			return nil, fmt.Errorf("walking Paprika directory: %w", err)
		}
		sort.Strings(paths)
	} else if strings.EqualFold(filepath.Ext(path), ".paprika") {
		archive, err := zip.OpenReader(path)
		if err != nil {
			return nil, fmt.Errorf("opening Paprika archive: %w", err)
		}
		defer archive.Close()
		result := make([]paprikaImportRecipe, 0, len(archive.File))
		for _, entry := range archive.File {
			if !entry.FileInfo().Mode().IsRegular() || !strings.EqualFold(filepath.Ext(entry.Name), ".paprikarecipe") {
				continue
			}
			reader, err := entry.Open()
			if err != nil {
				return nil, fmt.Errorf("opening archived recipe %s: %w", entry.Name, err)
			}
			recipes, readErr := readPaprikaRecipe(path+"!"+entry.Name, reader)
			closeErr := reader.Close()
			if readErr != nil {
				return nil, readErr
			}
			if closeErr != nil {
				return nil, fmt.Errorf("closing archived recipe %s: %w", entry.Name, closeErr)
			}
			result = append(result, recipes...)
		}
		sort.Slice(result, func(i, j int) bool { return result[i].SourcePath < result[j].SourcePath })
		return result, nil
	} else {
		paths = []string{path}
	}
	result := make([]paprikaImportRecipe, 0, len(paths))
	for _, candidate := range paths {
		file, err := os.Open(candidate)
		if err != nil {
			return nil, fmt.Errorf("opening %s: %w", candidate, err)
		}
		recipes, readErr := readPaprikaRecipe(candidate, file)
		closeErr := file.Close()
		if readErr != nil {
			return nil, readErr
		}
		if closeErr != nil {
			return nil, fmt.Errorf("closing %s: %w", candidate, closeErr)
		}
		result = append(result, recipes...)
	}
	return result, nil
}

func mergePaprikaRecipe(existing, imported *pb.PBRecipe) *pb.PBRecipe {
	merged := proto.Clone(existing).(*pb.PBRecipe)
	merged.Name = imported.GetName()
	merged.Note = imported.GetNote()
	merged.SourceName = imported.GetSourceName()
	merged.SourceUrl = imported.GetSourceUrl()
	merged.NutritionalInfo = imported.GetNutritionalInfo()
	merged.Servings = imported.GetServings()
	merged.PrepTime = imported.GetPrepTime()
	merged.CookTime = imported.GetCookTime()
	merged.Rating = imported.GetRating()
	merged.PaprikaIdentifier = imported.GetPaprikaIdentifier()
	merged.Ingredients = imported.GetIngredients()
	merged.PreparationSteps = imported.GetPreparationSteps()
	return merged
}

type paprikaImportPlan struct {
	Imported   paprikaImportRecipe
	Recipe     *pb.PBRecipe
	Existing   *pb.PBRecipe
	Action     string
	SkipReason string
}

func normalizedRecipeName(name string) string {
	return strings.ToLower(strings.TrimSpace(name))
}

func indexPaprikaRecipes(recipes []*pb.PBRecipe) (map[string][]*pb.PBRecipe, map[string][]*pb.PBRecipe) {
	byPaprikaID := make(map[string][]*pb.PBRecipe)
	byName := make(map[string][]*pb.PBRecipe)
	for _, recipe := range recipes {
		if id := strings.TrimSpace(recipe.GetPaprikaIdentifier()); id != "" {
			byPaprikaID[id] = append(byPaprikaID[id], recipe)
		}
		if name := normalizedRecipeName(recipe.GetName()); name != "" {
			byName[name] = append(byName[name], recipe)
		}
	}
	return byPaprikaID, byName
}

func planPaprikaImports(imports []paprikaImportRecipe, existing []*pb.PBRecipe, updateExisting bool) ([]paprikaImportPlan, error) {
	byPaprikaID, byName := indexPaprikaRecipes(existing)
	seenPaprikaID := map[string]bool{}
	seenName := map[string]bool{}
	plans := make([]paprikaImportPlan, 0, len(imports))
	for _, imported := range imports {
		candidate := imported.Recipe
		paprikaID := strings.TrimSpace(candidate.GetPaprikaIdentifier())
		name := normalizedRecipeName(candidate.GetName())
		if name == "" {
			return nil, fmt.Errorf("%s: imported recipe has an empty normalized name", imported.SourcePath)
		}

		var matches []*pb.PBRecipe
		if paprikaID != "" {
			matches = byPaprikaID[paprikaID]
		}
		if len(matches) == 0 {
			matches = byName[name]
		}
		if len(matches) > 1 {
			if updateExisting {
				return nil, fmt.Errorf("%s: ambiguous existing recipe match for %q", imported.SourcePath, candidate.GetName())
			}
			plans = append(plans, paprikaImportPlan{Imported: imported, Recipe: candidate, Action: "skip", SkipReason: "ambiguous-existing"})
			continue
		}

		duplicateInput := false
		if paprikaID != "" && seenPaprikaID[paprikaID] {
			duplicateInput = true
		}
		if seenName[name] {
			duplicateInput = true
		}
		if duplicateInput {
			plans = append(plans, paprikaImportPlan{Imported: imported, Recipe: candidate, Action: "skip", SkipReason: "duplicate-input"})
			continue
		}
		if paprikaID != "" {
			seenPaprikaID[paprikaID] = true
		}
		seenName[name] = true

		if len(matches) == 1 {
			if !updateExisting {
				plans = append(plans, paprikaImportPlan{Imported: imported, Recipe: candidate, Existing: matches[0], Action: "skip", SkipReason: "existing"})
				continue
			}
			candidate = mergePaprikaRecipe(matches[0], candidate)
			plans = append(plans, paprikaImportPlan{Imported: imported, Recipe: candidate, Existing: matches[0], Action: "update"})
			continue
		}
		plans = append(plans, paprikaImportPlan{Imported: imported, Recipe: candidate, Action: "create"})
	}
	return plans, nil
}

func samePaprikaIngredients(actual, expected []*pb.PBIngredient) bool {
	if len(actual) != len(expected) {
		return false
	}
	for index := range expected {
		if actual[index].GetRawIngredient() != expected[index].GetRawIngredient() ||
			actual[index].GetName() != expected[index].GetName() ||
			actual[index].GetQuantity() != expected[index].GetQuantity() ||
			actual[index].GetNote() != expected[index].GetNote() {
			return false
		}
	}
	return true
}

func samePaprikaRecipeContent(actual, expected *pb.PBRecipe) bool {
	if actual == nil || expected == nil {
		return false
	}
	if actual.GetName() != expected.GetName() ||
		actual.GetNote() != expected.GetNote() ||
		actual.GetSourceName() != expected.GetSourceName() ||
		actual.GetSourceUrl() != expected.GetSourceUrl() ||
		actual.GetNutritionalInfo() != expected.GetNutritionalInfo() ||
		actual.GetServings() != expected.GetServings() ||
		actual.GetPrepTime() != expected.GetPrepTime() ||
		actual.GetCookTime() != expected.GetCookTime() ||
		actual.GetRating() != expected.GetRating() ||
		actual.GetPaprikaIdentifier() != expected.GetPaprikaIdentifier() ||
		!samePaprikaIngredients(actual.GetIngredients(), expected.GetIngredients()) {
		return false
	}
	if len(actual.GetPreparationSteps()) != len(expected.GetPreparationSteps()) {
		return false
	}
	for index := range expected.GetPreparationSteps() {
		if actual.GetPreparationSteps()[index] != expected.GetPreparationSteps()[index] {
			return false
		}
	}
	return true
}

func newRecipesImportPaprikaCmd(flags *rootFlags) *cobra.Command {
	var inputPath string
	var updateExisting bool
	var apply bool

	cmd := &cobra.Command{
		Use:         "import-paprika",
		Short:       "Preview or apply .paprika archive and .paprikarecipe imports",
		Example:     "  anylist-pp-cli recipes import-paprika --input testdata/paprika --json\n  anylist-pp-cli recipes import-paprika --input testdata/paprika --apply --json",
		Annotations: map[string]string{"pp:endpoint": "recipes.import-paprika", "pp:method": "POST", "pp:path": "/data/user-recipe-data/update"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if strings.TrimSpace(inputPath) == "" {
				return fmt.Errorf("required flag \"input\" not set")
			}
			imports, err := loadPaprikaInput(inputPath)
			if err != nil {
				return err
			}
			if len(imports) == 0 {
				return fmt.Errorf("no .paprikarecipe files found in %s", inputPath)
			}
			if !apply || dryRunOK(flags) {
				plans, err := planPaprikaImports(imports, nil, updateExisting)
				if err != nil {
					return err
				}
				created, skipped, duplicates := 0, 0, 0
				for _, plan := range plans {
					switch plan.Action {
					case "create":
						created++
					case "skip":
						skipped++
						if plan.SkipReason == "duplicate-input" {
							duplicates++
						}
					}
				}
				result := map[string]any{"preview": true, "input": inputPath, "files": len(imports), "recipes": len(imports), "planned_creates": created, "planned_skips": skipped, "duplicate_candidates": duplicates}
				if flags.asJSON {
					return printJSONFiltered(cmd.OutOrStdout(), result, flags)
				}
				fmt.Fprintf(cmd.OutOrStdout(), "Paprika import preview: %d recipes, %d planned creates, %d skips, %d duplicate candidates\n", len(imports), created, skipped, duplicates)
				return nil
			}
			cfg, st, err := openAuthedLocalStore(flags)
			if err != nil {
				return err
			}
			defer st.Close()
			ctx := cmd.Context()
			userData, recipeDataID, err := currentRecipeData(ctx, cfg)
			if err != nil {
				return fmt.Errorf("reading live recipe data: %w", err)
			}
			var existingRecipes []*pb.PBRecipe
			if data := userData.GetRecipeDataResponse(); data != nil {
				existingRecipes = data.GetRecipes()
			}
			plans, err := planPaprikaImports(imports, existingRecipes, updateExisting)
			if err != nil {
				return err
			}
			client := anylist.New(cfg)
			created, updated, skipped := 0, 0, 0
			written := map[string]*pb.PBRecipe{}
			for _, plan := range plans {
				if plan.Action == "skip" {
					skipped++
					continue
				}
				candidate := plan.Recipe
				if plan.Action == "update" {
					updated++
				} else {
					created++
				}
				if err := client.SaveRecipe(ctx, recipeDataID, candidate, false); err != nil {
					return fmt.Errorf("saving %q from %s: %w", candidate.GetName(), plan.Imported.SourcePath, err)
				}
				written[candidate.GetIdentifier()] = candidate
			}
			if len(written) > 0 {
				verifiedData, err := client.GetUserData(ctx)
				if err != nil {
					return fmt.Errorf("verifying Paprika import: %w", err)
				}
				for id, expected := range written {
					actual, found := findLiveRecipeByID(verifiedData, id)
					if !found || !samePaprikaRecipeContent(actual, expected) {
						return fmt.Errorf("Paprika import verification failed for %q", expected.GetName())
					}
				}
				if err := st.SyncFromUserData(verifiedData); err != nil {
					return fmt.Errorf("refreshing local cache after Paprika import: %w", err)
				}
			}
			result := map[string]any{"imported": true, "files": len(imports), "created": created, "updated": updated, "skipped": skipped}
			if flags.asJSON {
				return printJSONFiltered(cmd.OutOrStdout(), result, flags)
			}
			fmt.Fprintf(cmd.OutOrStdout(), "Paprika import complete: %d created, %d updated, %d skipped\n", created, updated, skipped)
			return nil
		},
	}
	cmd.Flags().StringVarP(&inputPath, "input", "i", "", "Paprika archive, .paprikarecipe file, or directory")
	cmd.Flags().BoolVar(&updateExisting, "update-existing", false, "Update matching recipes instead of skipping them")
	cmd.Flags().BoolVar(&apply, "apply", false, "Apply the validated import; preview is the default")
	return cmd
}
